35	import org.springframework.samples.petclinic.rest.dto.PetFieldsDto;
36	import org.springframework.samples.petclinic.rest.dto.VisitDto;
37	import org.springframework.samples.petclinic.rest.dto.VisitFieldsDto;
38	import org.springframework.samples.petclinic.service.ClinicService;
39	import org.springframework.security.access.prepost.PreAuthorize;
40	import org.springframework.web.bind.annotation.CrossOrigin;
41	import org.springframework.web.bind.annotation.RequestMapping;
42	import org.springframework.web.bind.annotation.RestController;
43	import org.springframework.web.server.ResponseStatusException;
44	import org.springframework.web.util.UriComponentsBuilder;
45	
46	import jakarta.transaction.Transactional;
47	
48	/**
49	 * @author Vitaliy Fedoriv
50	 */
51	
52	@RestController
53	@CrossOrigin(exposedHeaders = "errors, content-type")
54	@RequestMapping("/api")
55	public class OwnerRestControllerV1 implements OwnersApi {
56	
57	    private static final org.slf4j.Logger AUDIT = org.slf4j.LoggerFactory.getLogger("AUDIT");
58	
59	    private final ClinicService clinicService;
60	
61	    private final OwnerMapper ownerMapper;
62	
63	    private final PetMapper petMapper;
64	
65	    private final VisitMapper visitMapper;
66	
67	    public OwnerRestControllerV1(ClinicService clinicService,
68	                                 OwnerMapper ownerMapper,
69	                                 PetMapper petMapper,
70	                                 VisitMapper visitMapper) {
71	        this.clinicService = clinicService;
72	        this.ownerMapper = ownerMapper;
73	        this.petMapper = petMapper;
74	        this.visitMapper = visitMapper;
75	    }
76	
77	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
78	    @Override
79	    public ResponseEntity<List<OwnerDto>> listOwners(String lastName) {
80	        Collection<Owner> owners;
81	        if (lastName != null) {
82	            owners = this.clinicService.findOwnerByLastName(lastName);
83	        } else {
84	            owners = this.clinicService.findAllOwners();
85	        }
86	        if (owners.isEmpty()) {
87	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
88	        }
89	        return new ResponseEntity<>(ownerMapper.toOwnerDtoCollection(owners), HttpStatus.OK);
90	    }
91	
92	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
93	    @Override
94	    public ResponseEntity<OwnerDto> getOwner(Integer ownerId) {
95	        Owner owner = this.clinicService.findOwnerById(ownerId);
96	        if (owner == null) {
97	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
98	        }
99	        return new ResponseEntity<>(ownerMapper.toOwnerDto(owner), HttpStatus.OK);
100	    }
101	
102	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
103	    @Override
104	    public ResponseEntity<OwnerDto> addOwner(OwnerFieldsDto ownerFieldsDto) {
105	        HttpHeaders headers = new HttpHeaders();
106	        Owner owner = ownerMapper.toOwner(ownerFieldsDto);
107	        applyAddress(owner);
108	        String normalizedTelephone = normalizeTelephone(owner.getTelephone());
109	        owner.setTelephone(normalizedTelephone);
110	        owner.setEmail(normalizeEmail(owner.getEmail()));
111	        validateEmailDomain(owner.getEmail());
112	        validatePostcode(owner.getPostcode(), owner.getCity());
113	        java.time.LocalDate serverDate = java.time.LocalDate.now();
114	        if (owner.getRegistrationDate() != null && owner.getRegistrationDate().isAfter(serverDate)) {
115	            throw new ResponseStatusException(HttpStatus.BAD_REQUEST,
116	                "Registration date must not be later than the current server date");
117	        }
118	        java.time.LocalDate effectiveDate = owner.getRegistrationDate() != null
119	            ? owner.getRegistrationDate() : serverDate;
120	        java.time.LocalDate businessDate = toBusinessDay(effectiveDate);
121	        owner.setRegistrationDate(businessDate);
122	        long createdToday = this.clinicService.findAllOwners().stream()
123	            .map(Owner::getRegistrationDate)
124	            .filter(businessDate::equals)
125	            .count();
126	        if (createdToday >= 100) {
127	            throw new ResponseStatusException(HttpStatus.TOO_MANY_REQUESTS,
128	                "The maximum number of owners for today has already been reached");
129	        }
130	        owner.setBulkSignupWarning(createdToday > 80);
131	        // The household is keyed deterministically on (normalized last name, postcode): every owner
132	        // computes the same householdId from those two fields, so owners sharing a last name and
133	        // postcode belong to the same household automatically, without any explicit linking.
134	        String lastNameKey = normalizeForHousehold(owner.getLastName());
135	        String householdId = householdId(lastNameKey, owner.getPostcode());
136	        owner.setHouseholdId(householdId);
137	        List<Owner> householdMembers = this.clinicService.findAllOwners().stream()
138	            .filter(existing -> householdId.equals(
139	                householdId(normalizeForHousehold(existing.getLastName()), existing.getPostcode())))
140	            .toList();
141	        // All duplicate detection is expressed through the single derived identityKey
142	        // (telephone|email|householdId); a new owner is rejected only when its whole key matches.
143	        String identityKey = owner.getIdentityKey();
144	        boolean identityInUse = this.clinicService.findAllOwners().stream()
145	            .anyMatch(existing -> identityKey.equals(existing.getIdentityKey()));
146	        if (identityInUse) {
147	            throw new ResponseStatusException(HttpStatus.CONFLICT,
148	                "An owner with this identity already exists");
149	        }
150	        // Because the household is keyed on (last name, postcode), a second owner sharing a last name
151	        // and postcode with an existing owner is the same household and is rejected as a household
152	        // duplicate (409). Declaring 'sharesHousehold' only bypasses this block, creating the owner as
153	        // a declared household member.
154	        boolean declaredHouseholdMember = Boolean.TRUE.equals(ownerFieldsDto.getSharesHousehold());
155	        if (!householdMembers.isEmpty() && !declaredHouseholdMember) {
156	            throw new ResponseStatusException(HttpStatus.CONFLICT,
157	                "An owner in this household already exists");
158	        }
159	        String cityKey = normalizeForHousehold(owner.getCity());
160	        long cityCount = this.clinicService.findAllOwners().stream()
161	            .filter(existing -> normalizeForHousehold(existing.getCity()).equals(cityKey))
162	            .count();
163	        if (cityCount >= 50) {
164	            throw new ResponseStatusException(HttpStatus.CONFLICT,
165	                "This city already has the maximum number of owners");
166	        }
167	        owner.setNamesakeCount(namesakeCount(owner.getFirstName(), owner.getLastName()));
168	        owner.setHouseholdSize(householdMembers.size() + 1);
169	        // The former soft-match (same last name and postcode, different telephone) now coincides
170	        // exactly with the household key: such an owner is either rejected as a household duplicate
171	        // above, or, when it declares 'sharesHousehold', created as a declared household member. A
172	        // declared member is not a suspected duplicate, so no owner is ever flagged here.
173	        owner.setPossibleDuplicate(false);
174	        owner.setPossibleDuplicateOf(null);
175	        owner.setCustomerCode(deduplicateCustomerCode(customerCode(owner.getCity(), owner.getPostcode(),
176	            owner.getTelephone(), owner.getLastName())));
177	        this.clinicService.saveOwner(owner);
178	        OwnerDto ownerDto = ownerMapper.toOwnerDto(owner);
179	        AUDIT.info("Owner created: id={} customerCode={} registrationDate={} membershipLevel={} membershipNumber={}",
180	            owner.getId(), owner.getCustomerCode(), owner.getRegistrationDate(), ownerDto.getMembershipLevel(),
181	            ownerDto.getMembershipNumber());
182	        headers.setLocation(UriComponentsBuilder.newInstance()
183	            .path("/api/owners/{id}").buildAndExpand(owner.getId()).toUri());
184	        return new ResponseEntity<>(ownerDto, headers, HttpStatus.CREATED);
185	    }
186	
187	    /**
188	     * Rolls a registration date forward to a business day. When {@code date} falls on a Saturday or
189	     * Sunday it is advanced to the following Monday; a weekday is returned unchanged. This is applied
190	     * to the effective registration date (whether supplied in the request or defaulted to the server
191	     * date) so that every stored {@code registrationDate}, and any value derived from it, lands on a
192	     * business day.
193	     *
194	     * @param date the effective registration date
195	     * @return the same date if it is a weekday, otherwise the following Monday
196	     */
197	    private java.time.LocalDate toBusinessDay(java.time.LocalDate date) {
198	        return switch (date.getDayOfWeek()) {
199	            case SATURDAY -> date.plusDays(2);
200	            case SUNDAY -> date.plusDays(1);
201	            default -> date;
202	        };
203	    }
204	
205	    /**
206	     * Counts the owners that already exist (before the current create) whose first and last names
207	     * both match the supplied names, compared case-insensitively. The returned value is captured on
208	     * the new owner at creation time and does not change as further owners are added later.
209	     *
210	     * @param firstName the new owner's first name
211	     * @param lastName  the new owner's last name
212	     * @return the number of pre-existing namesake owners
213	     */
214	    private int namesakeCount(String firstName, String lastName) {
215	        return (int) this.clinicService.findAllOwners().stream()
216	            .filter(existing -> existing.getFirstName() != null
217	                && existing.getFirstName().equalsIgnoreCase(firstName)
218	                && existing.getLastName() != null
219	                && existing.getLastName().equalsIgnoreCase(lastName))
220	            .count();
221	    }
222	
223	    /**
224	     * Builds the customer code for a new owner, formatted {@code '<REGION>-<HASH8>'} where
225	     * {@code REGION} is the canonical region derived from the owner's postcode (falling back to
226	     * the city when the postcode is absent or in no known range, see
227	     * {@link org.springframework.samples.petclinic.mapper.Localities#forCityAndPostcode}), and
228	     * {@code HASH8} is the first 8 upper-case hex characters of the SHA-256 digest of the
229	     * normalized telephone concatenated with the last name (e.g. {@code 'NSW-1A2B3C4D'}). Unlike
230	     * the previous city-prefixed scheme it carries no per-city sequence number, so the identity is
231	     * a pure function of the owner's region, telephone and last name.
232	     *
233	     * @param city                the owner's city
234	     * @param postcode            the owner's postcode, may be {@code null}
235	     * @param normalizedTelephone the owner's telephone, already normalized to E.164
236	     * @param lastName            the owner's last name
237	     * @return the assigned customer code
238	     */
239	    private String customerCode(String city, String postcode, String normalizedTelephone, String lastName) {
240	        String region = org.springframework.samples.petclinic.mapper.Localities
241	            .forCityAndPostcode(city, postcode);
242	        String hash8 = sha256UpperHex((normalizedTelephone == null ? "" : normalizedTelephone)
243	            + (lastName == null ? "" : lastName), 8);
244	        return region + "-" + hash8;
245	    }
246	
247	    /**
248	     * Ensures the computed {@code customerCode} is unique across existing owners. When {@code baseCode}
249	     * does not collide with any existing owner's {@code customerCode} it is returned unchanged.
250	     * Otherwise {@code '-<n>'} is appended, using the smallest {@code n} of 2 or more that yields a
251	     * value not already in use, and that de-duplicated code is returned.
252	     *
253	     * @param baseCode the freshly computed customer code
254	     * @return {@code baseCode} if unused, otherwise {@code baseCode + "-" + n} for the smallest free n
255	     */
256	    private String deduplicateCustomerCode(String baseCode) {
257	        java.util.Set<String> inUse = this.clinicService.findAllOwners().stream()
258	            .map(org.springframework.samples.petclinic.model.Owner::getCustomerCode)
259	            .filter(java.util.Objects::nonNull)
260	            .collect(java.util.stream.Collectors.toSet());
261	        if (!inUse.contains(baseCode)) {
262	            return baseCode;
263	        }
264	        int n = 2;
265	        while (inUse.contains(baseCode + "-" + n)) {
266	            n++;
267	        }
268	        return baseCode + "-" + n;
269	    }
270	
271	    /**
272	     * Returns the first {@code length} upper-case hex characters of the SHA-256 digest of the
273	     * UTF-8 bytes of {@code value}.
274	     *
275	     * @param value  the source value to hash
276	     * @param length the number of leading hex characters to return
277	     * @return the leading upper-case hex characters of the digest
278	     */
279	    private String sha256UpperHex(String value, int length) {
280	        try {
281	            byte[] digest = java.security.MessageDigest.getInstance("SHA-256")
282	                .digest(value.getBytes(java.nio.charset.StandardCharsets.UTF_8));
283	            StringBuilder sb = new StringBuilder(digest.length * 2);
284	            for (byte b : digest) {
285	                sb.append(String.format("%02x", b));
286	            }
287	            return sb.substring(0, length).toUpperCase(java.util.Locale.ROOT);
288	        }
289	        catch (java.security.NoSuchAlgorithmException e) {
290	            throw new IllegalStateException("SHA-256 not available", e);
291	        }
292	    }
293	
294	    /**
295	     * Normalizes a street address applied whenever an owner is created: leading and trailing
296	     * whitespace is trimmed, any internal run of whitespace is collapsed to a single space, the
297	     * value is upper-cased, and common street-type abbreviations are expanded to their full form
298	     * ({@code ST -> STREET}, {@code RD -> ROAD}, {@code AVE -> AVENUE}). The expansion is applied
299	     * per whitespace-delimited token, so only standalone abbreviations are expanded. A {@code null}
300	     * value normalizes to the empty string. So {@code '  12  main  st '} becomes
301	     * {@code '12 MAIN STREET'}.
302	     *
303	     * @param address the raw address as submitted, or {@code null} when absent
304	     * @return the normalized address, or the empty string when the value is blank
305	     */
306	    /**
307	     * Resolves and normalizes an owner's postal address, accepting either the structured form
308	     * ({@code addressLine1} plus an optional {@code addressLine2}) or the flat {@code address}
309	     * input for backward compatibility. The structured form is preferred: when a non-blank
310	     * {@code addressLine1} is supplied, both structured lines are normalized (see
311	     * {@link #normalizeAddress(String)}) and the stored {@code address} is composed from them —
312	     * the normalized {@code addressLine1}, with a single space and the normalized
313	     * {@code addressLine2} appended when an {@code addressLine2} is present. Otherwise the flat
314	     * {@code address} input is normalized and stored, and the structured lines are cleared.
315	     *
316	     * <p>An owner is valid only when it supplies an address in one of these forms; a request with
317	     * neither a non-blank {@code addressLine1} nor a non-blank flat {@code address} is rejected.
318	     *
319	     * @param owner the owner whose address fields are resolved and normalized in place
320	     * @throws ResponseStatusException with a 400 status when no address is supplied in either form
321	     */
322	    private void applyAddress(Owner owner) {
323	        String line1 = normalizeAddress(owner.getAddressLine1());
324	        String line2 = normalizeAddress(owner.getAddressLine2());
325	        String flat = normalizeAddress(owner.getAddress());
326	        String composed;
327	        if (!line1.isEmpty()) {
328	            composed = line2.isEmpty() ? line1 : line1 + " " + line2;
329	            owner.setAddressLine1(line1);
330	            owner.setAddressLine2(line2.isEmpty() ? null : line2);
331	        } else {
332	            composed = flat;
333	            owner.setAddressLine1(null);
334	            owner.setAddressLine2(null);
335	        }
336	        if (composed.isEmpty()) {
337	            throw new ResponseStatusException(HttpStatus.BAD_REQUEST,
338	                "Address must not be blank after normalization");
339	        }
340	        owner.setAddress(composed);
341	    }
342	
343	    private String normalizeAddress(String address) {
344	        String collapsed = (address == null ? "" : address)
345	            .trim().replaceAll("\\s+", " ").toUpperCase(java.util.Locale.ROOT);
346	        if (collapsed.isEmpty()) {
347	            return "";
348	        }
349	        String[] tokens = collapsed.split(" ");
350	        for (int i = 0; i < tokens.length; i++) {
351	            switch (tokens[i]) {
352	                case "ST" -> tokens[i] = "STREET";
353	                case "RD" -> tokens[i] = "ROAD";
354	                case "AVE" -> tokens[i] = "AVENUE";
355	                default -> { }
356	            }
357	        }
358	        return String.join(" ", tokens);
359	    }
360	
361	    /**
362	     * Normalizes a value for household-duplicate comparison: leading and trailing whitespace is
363	     * trimmed, any internal run of whitespace is collapsed to a single space, and the result is
364	     * lower-cased so the comparison is case-insensitive. A {@code null} value normalizes to the
365	     * empty string.
366	     *
367	     * @param value the raw value (last name or address) as submitted
368	     * @return the normalized comparison key
369	     */
370	    private String normalizeForHousehold(String value) {
371	        if (value == null) {
372	            return "";
373	        }
374	        return value.trim().replaceAll("\\s+", " ").toLowerCase(java.util.Locale.ROOT);
375	    }
376	
377	    /**
378	     * Derives the stable shared household identifier for a household, keyed on the normalized last
379	     * name and address. Because it is a pure function of those normalized keys, every owner in the
380	     * same household deterministically computes the same value. The identifier is the first 12
381	     * upper-case hex characters of the SHA-256 digest of the two keys joined with a NUL separator
382	     * (the separator prevents distinct name/address pairs from colliding).
383	     *
384	     * @param lastNameKey the normalized last-name comparison key
385	     * @param addressKey  the normalized address comparison key
386	     * @return the stable household identifier
387	     */
388	    private String householdId(String lastNameKey, String postcode) {
389	        String seed = lastNameKey + "|" + (postcode == null ? "" : postcode);
390	        try {
391	            byte[] digest = java.security.MessageDigest.getInstance("SHA-256")
392	                .digest(seed.getBytes(java.nio.charset.StandardCharsets.UTF_8));
393	            StringBuilder sb = new StringBuilder(digest.length * 2);
394	            for (byte b : digest) {
395	                sb.append(String.format("%02x", b));
396	            }
397	            return sb.substring(0, 12).toUpperCase(java.util.Locale.ROOT);
398	        }
399	        catch (java.security.NoSuchAlgorithmException e) {
400	            throw new IllegalStateException("SHA-256 not available", e);
401	        }
402	    }
403	
404	    /**
405	     * The exact number of national (subscriber) digits required for a given country calling code,
406	     * i.e. the digits that follow the country code in an E.164 number. A country code that is not
407	     * listed here has no fixed-length requirement beyond the general 8-to-15-digit E.164 bound.
408	     * Australia ({@code '+61'}) requires 9 national digits and the NANP ({@code '+1'}) requires 10.
409	     */
410	    private static final java.util.Map<String, Integer> NATIONAL_NUMBER_LENGTHS =
411	        java.util.Map.of("61", 9, "1", 10);
412	
413	    /**
414	     * Normalizes a telephone number to E.164 form. Spaces, dashes and brackets (indeed any
415	     * non-digit character) are stripped. If the submitted value carries a leading {@code '+'}
416	     * its country code is kept as-is; otherwise the default country code {@code '+61'} is
417	     * assumed and a single leading {@code '0'} is dropped from the national digits. The
418	     * resulting value must be a {@code '+'} followed by 8 to 15 digits. So {@code '0412 345 678'}
419	     * is stored as {@code '+61412345678'}.
420	     *
421	     * <p>In addition, when the number's country code has a fixed national-number length (see
422	     * {@link #NATIONAL_NUMBER_LENGTHS}), the national digits that follow the country code must
423	     * match that length exactly: {@code '+61'} requires 9 national digits and {@code '+1'}
424	     * requires 10. So {@code '+61 123'} is rejected because its 3 national digits are not 9.
425	     *
426	     * @param telephone the raw telephone number as submitted
427	     * @return the normalized E.164 telephone number
428	     * @throws ResponseStatusException with a 400 status if the value cannot form a valid E.164
429	     *         number (8 to 15 digits after the '+'), or if its national-number length is wrong
430	     *         for its country code
431	     */
432	    private String normalizeTelephone(String telephone) {
433	        String raw = telephone == null ? "" : telephone.trim();
434	        String digits = raw.replaceAll("\\D", "");
435	        String e164;
436	        if (raw.startsWith("+")) {
437	            e164 = "+" + digits;
438	        } else {
439	            if (digits.startsWith("0")) {
440	                digits = digits.substring(1);
441	            }
442	            e164 = "+61" + digits;
443	        }
444	        int digitCount = e164.length() - 1;
445	        if (digitCount < 8 || digitCount > 15) {
446	            throw new ResponseStatusException(HttpStatus.BAD_REQUEST,
447	                "Telephone must form a valid E.164 number with 8 to 15 digits after the '+'");
448	        }
449	        validateNationalNumberLength(e164);
450	        return e164;
451	    }
452	
453	    /**
454	     * Validates that an E.164 number's national-number length is correct for its country code.
455	     * The country code is matched by longest known prefix (so {@code '+61'} is preferred over
456	     * {@code '+1'} would-be matches); when the code has a fixed national-number length the digits
457	     * following it must match exactly. Country codes without a fixed length are left unchecked.
458	     *
459	     * @param e164 the normalized E.164 number (a {@code '+'} followed by digits)
460	     * @throws ResponseStatusException with a 400 status if the national-number length is wrong
461	     *         for the country code
462	     */
463	    private void validateNationalNumberLength(String e164) {
464	        String allDigits = e164.substring(1);
465	        String bestCode = null;
466	        for (String code : NATIONAL_NUMBER_LENGTHS.keySet()) {
467	            if (allDigits.startsWith(code)
468	                    && (bestCode == null || code.length() > bestCode.length())) {
469	                bestCode = code;
470	            }
471	        }
472	        if (bestCode == null) {
473	            return;
474	        }
475	        int nationalLength = allDigits.length() - bestCode.length();
476	        int required = NATIONAL_NUMBER_LENGTHS.get(bestCode);
477	        if (nationalLength != required) {
478	            throw new ResponseStatusException(HttpStatus.BAD_REQUEST,
479	                "Telephone for country code '+" + bestCode + "' must have " + required
480	                    + " national digits");
481	        }
482	    }
483	
484	    /**
485	     * The inclusive 4-digit postcode range permitted for each canonical region, keyed by the
486	     * region derived from the owner's city ({@code Sydney -> NSW}, {@code Melbourne -> VIC},
487	     * {@code Brisbane -> QLD}): NSW {@code 2000-2099}, VIC {@code 3000-3099}, QLD
488	     * {@code 4000-4099}. A city whose region is not listed here accepts any 4-digit postcode.
489	     */
490	    private static final java.util.Map<String, int[]> REGION_POSTCODE_RANGES = java.util.Map.of(
491	        "NSW", new int[] {2000, 2099},
492	        "VIC", new int[] {3000, 3099},
493	        "QLD", new int[] {4000, 4099});
494	
495	    /**
496	     * Validates an owner's optional postcode against their city's region. The postcode is only
497	     * checked when present (a {@code null} postcode is accepted, keeping the request contract
498	     * backward-compatible). Its four-digit shape is already enforced by Bean Validation on the
499	     * request DTO. When the city maps to a known region (see {@link #REGION_POSTCODE_RANGES}) the
500	     * postcode must fall within that region's inclusive range; a city with no known region accepts
501	     * any 4-digit postcode.
502	     *
503	     * @param postcode the owner's postcode as submitted, or {@code null} when absent
504	     * @param city     the owner's city, used to derive the region whose range applies
505	     * @throws ResponseStatusException with a 400 status when a supplied postcode is out of range
506	     *         for the city's region
507	     */
508	    private void validatePostcode(String postcode, String city) {
509	        if (postcode == null) {
510	            return;
511	        }
512	        String region = org.springframework.samples.petclinic.mapper.Localities.forCity(city);
513	        int[] range = REGION_POSTCODE_RANGES.get(region);
514	        if (range == null) {
515	            return;
516	        }
517	        int value = Integer.parseInt(postcode);
518	        if (value < range[0] || value > range[1]) {
519	            throw new ResponseStatusException(HttpStatus.BAD_REQUEST,
520	                "Postcode " + postcode + " is not valid for region " + region);
521	        }
522	    }
523	
524	    /**
525	     * Normalizes an optional email address by lower-casing it. Syntactic validity is enforced
526	     * by Bean Validation on the request DTO, so a value reaching this point is either {@code null}
527	     * (absent) or already valid.
528	     *
529	     * @param email the email address as submitted, or {@code null} when absent
530	     * @return the lower-cased email, or {@code null} when absent
531	     */
532	    private String normalizeEmail(String email) {
533	        return email == null ? null : email.toLowerCase(java.util.Locale.ROOT);
534	    }
535	
536	    /**
537	     * The set of disposable email domains an owner's email may not use. These throwaway-mailbox
538	     * providers are rejected because they cannot be relied on for durable contact.
539	     */
540	    private static final java.util.Set<String> DISPOSABLE_EMAIL_DOMAINS = java.util.Set.of(
541	        "mailinator.com", "tempmail.com", "guerrillamail.com");
542	
543	    /**
544	     * Rejects an owner whose email domain is on the disposable-domain blocklist. The email has
545	     * already been normalized to lower-case, so the domain (the part after the last {@code '@'}) is
546	     * compared case-insensitively against {@link #DISPOSABLE_EMAIL_DOMAINS}. A {@code null} email
547	     * (absent) is accepted, keeping the field optional.
548	     *
549	     * @param email the normalized email address, or {@code null} when absent
550	     * @throws ResponseStatusException with a 400 status when the email domain is blocklisted
551	     */
552	    private void validateEmailDomain(String email) {
553	        if (email == null) {
554	            return;
555	        }
556	        int at = email.lastIndexOf('@');
557	        if (at < 0) {
558	            return;
559	        }
560	        String domain = email.substring(at + 1);
561	        if (DISPOSABLE_EMAIL_DOMAINS.contains(domain)) {
562	            throw new ResponseStatusException(HttpStatus.BAD_REQUEST,
563	                "Email domain " + domain + " is not allowed");
564	        }
565	    }
566	
567	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
568	    @Override
569	    public ResponseEntity<OwnerDto> updateOwner(Integer ownerId, OwnerFieldsDto ownerFieldsDto) {
570	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
571	        if (currentOwner == null) {
572	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
573	        }
574	        currentOwner.setAddress(ownerFieldsDto.getAddress());
575	        currentOwner.setCity(ownerFieldsDto.getCity());
576	        currentOwner.setFirstName(ownerFieldsDto.getFirstName());
577	        currentOwner.setLastName(ownerFieldsDto.getLastName());
578	        currentOwner.setTelephone(normalizeTelephone(ownerFieldsDto.getTelephone()));
579	        currentOwner.setEmail(normalizeEmail(ownerFieldsDto.getEmail()));
580	        this.clinicService.saveOwner(currentOwner);
581	        return new ResponseEntity<>(ownerMapper.toOwnerDto(currentOwner), HttpStatus.NO_CONTENT);
582	    }
583	
584	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
585	    @Transactional
586	    @Override
587	    public ResponseEntity<OwnerDto> deleteOwner(Integer ownerId) {
588	        Owner owner = this.clinicService.findOwnerById(ownerId);
589	        if (owner == null) {
590	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
591	        }
592	        this.clinicService.deleteOwner(owner);
593	        return new ResponseEntity<>(HttpStatus.NO_CONTENT);
594	    }
595	
596	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
597	    @Override
598	    public ResponseEntity<PetDto> addPetToOwner(Integer ownerId, PetFieldsDto petFieldsDto) {
599	        Owner owner = this.clinicService.findOwnerById(ownerId);
600	        if (owner == null) {
601	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
602	        }
603	        HttpHeaders headers = new HttpHeaders();
604	        Pet pet = petMapper.toPet(petFieldsDto);
605	        owner.setId(ownerId);
606	        pet.setOwner(owner);
607	        pet.getType().setName(null);
608	        this.clinicService.savePet(pet);
609	        PetDto petDto = petMapper.toPetDto(pet);
610	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/pets/{id}")
611	            .buildAndExpand(pet.getId()).toUri());
612	        return new ResponseEntity<>(petDto, headers, HttpStatus.CREATED);
613	    }
614	
615	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
616	    @Override
617	    public ResponseEntity<Void> updateOwnersPet(Integer ownerId, Integer petId, PetFieldsDto petFieldsDto) {
618	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
619	        if (currentOwner != null) {
620	            Pet currentPet = this.clinicService.findPetById(petId);
621	            if (currentPet != null) {
622	                currentPet.setBirthDate(petFieldsDto.getBirthDate());
623	                currentPet.setName(petFieldsDto.getName());
624	                currentPet.setType(petMapper.toPetType(petFieldsDto.getType()));
625	                this.clinicService.savePet(currentPet);
626	                return new ResponseEntity<>(HttpStatus.NO_CONTENT);
627	            }
628	        }
629	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
630	    }
631	
632	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
633	    @Override
634	    public ResponseEntity<VisitDto> addVisitToOwner(Integer ownerId, Integer petId, VisitFieldsDto visitFieldsDto) {
635	        HttpHeaders headers = new HttpHeaders();
636	        Visit visit = visitMapper.toVisit(visitFieldsDto);
637	        Pet pet = new Pet();
638	        pet.setId(petId);
639	        visit.setPet(pet);
640	        this.clinicService.saveVisit(visit);
641	        VisitDto visitDto = visitMapper.toVisitDto(visit);
642	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/visits/{id}")
643	            .buildAndExpand(visit.getId()).toUri());
644	        return new ResponseEntity<>(visitDto, headers, HttpStatus.CREATED);
645	    }
646	
647	
648	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
649	    @Override
650	    public ResponseEntity<PetDto> getOwnersPet(Integer ownerId, Integer petId) {
651	        Owner owner = this.clinicService.findOwnerById(ownerId);
652	        if (owner != null) {
653	            Pet pet = owner.getPet(petId);
654	            if (pet != null) {
655	                return new ResponseEntity<>(petMapper.toPetDto(pet), HttpStatus.OK);
656	            }
657	        }
658	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
659	    }
660	}
