143	    /**
144	     * The known E.164 country calling codes used to split the stored telephone into its country
145	     * code and national digits when formatting {@link #getTelephoneDisplay()}. Ordered
146	     * longest-first so the most specific code wins; this mirrors the codes the application
147	     * recognises elsewhere (Australia {@code '+61'} and the NANP {@code '+1'}).
148	     */
149	    private static final List<String> KNOWN_COUNTRY_CODES = List.of("61", "1");
150	
151	    /**
152	     * The stored E.164 {@link #telephone} formatted for humans: the country code, a space, then the
153	     * national digits grouped in threes from the left and separated by spaces. So the stored
154	     * {@code '+61412345678'} is displayed as {@code '+61 412 345 678'}. The raw {@link #telephone}
155	     * itself is left in E.164 form. A {@code null} telephone yields {@code null}, and a value not in
156	     * E.164 form (no leading {@code '+'}) is returned unchanged.
157	     *
158	     * @return the human-formatted telephone, or {@code null} when no telephone is stored
159	     */
160	    @Transient
161	    public String getTelephoneDisplay() {
162	        if (this.telephone == null || !this.telephone.startsWith("+")) {
163	            return this.telephone;
164	        }
165	        String allDigits = this.telephone.substring(1);
166	        if (allDigits.isEmpty()) {
167	            return this.telephone;
168	        }
169	        String countryCode = null;
170	        for (String code : KNOWN_COUNTRY_CODES) {
171	            if (allDigits.startsWith(code)) {
172	                countryCode = code;
173	                break;
174	            }
175	        }
176	        if (countryCode == null) {
177	            countryCode = allDigits.substring(0, 1);
178	        }
179	        String national = allDigits.substring(countryCode.length());
180	        StringBuilder display = new StringBuilder("+").append(countryCode);
181	        for (int i = 0; i < national.length(); i += 3) {
182	            display.append(' ').append(national, i, Math.min(i + 3, national.length()));
183	        }
184	        return display.toString();
185	    }
