211	    /**
212	     * Derives the owner's age band from a birth date, computed against the reference date
213	     * (the registration date): {@code 'MINOR'} when under 18, {@code 'ADULT'} from 18 to 64,
214	     * and {@code 'SENIOR'} at 65 or older. The completed-years age is the whole number of years
215	     * between the birth date and the reference date. Returns {@code null} when no birth date is
216	     * supplied. When the reference date is absent the current server date is used.
217	     *
218	     * @param birthDate the owner's date of birth, or {@code null} when absent
219	     * @param reference the date to compute the age against (the registration date), may be {@code null}
220	     * @return {@code 'MINOR'}, {@code 'ADULT'} or {@code 'SENIOR'}, or {@code null} when no birth date
221	     */
222	    public static String ageBandOf(LocalDate birthDate, LocalDate reference) {
223	        if (birthDate == null) {
224	            return null;
225	        }
226	        LocalDate asOf = reference != null ? reference : LocalDate.now();
227	        int years = java.time.Period.between(birthDate, asOf).getYears();
228	        if (years < 18) {
229	            return "MINOR";
230	        }
231	        if (years < 65) {
232	            return "ADULT";
233	        }
234	        return "SENIOR";
235	    }
